const resp = $.steps.createNote.response || {};
const data = resp.data || {};
const id = data.id || {};

return {
  noteId: id.note_id || '',
  parentObject: data.parent_object || $.input.parentObject,
  parentRecordId: data.parent_record_id || $.input.parentRecordId,
  title: data.title || $.input.title,
  createdAt: data.created_at || '',
  summary: id.note_id
    ? `Created note "${$.input.title}" on ${$.input.parentObject} record ${$.input.parentRecordId}`
    : 'Failed to create note'
};
